<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Paginator from 'primevue/paginator';
import Dialog from 'primevue/dialog';
import RadioButton from 'primevue/radiobutton';
import Textarea from 'primevue/textarea';
import Select from 'primevue/select';
import apiClient from '../services/apiClient';
import { useRoute } from 'vue-router';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('PendingAds');
const route = useRoute();
const ads = ref([]); const banks = ref([]); const loading = ref(false); const refreshing = ref(false); const search = ref(''); const bankId = ref(null); const error = ref('');
const meta = ref({ current_page: 1, total: 0, per_page: 10 }); const selectedAd = ref(null); const approveTarget = ref(null); const rejectTarget = ref(null); const rejectionReason = ref(''); const rejectionDetails = ref(''); const acting = ref(false);
const reasons = ['مغایرت در مبالغ اعلامی', 'نقض قوانین بانکی', 'شماره تماس یا متن نامتعارف', 'مشخصات ناقص طرح'];
const queueCount = computed(() => meta.value.total || ads.value.length);
const formatNumber = (value) => value ? new Intl.NumberFormat('fa-IR').format(value) : '-';
const formatMoney = (value) => value ? `${formatNumber(value)} میلیون تومان` : 'ثبت نشده';
const formatDate = (value) => value ? new Intl.DateTimeFormat('fa-IR', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '-';
const relativeTime = (value) => { if (!value) return '-'; const minutes = Math.max(1, Math.floor((Date.now() - new Date(value).getTime()) / 60000)); return minutes < 60 ? `${new Intl.NumberFormat('fa-IR').format(minutes)} دقیقه پیش` : formatDate(value); };
const locationLabel = (ad) => [ad.location?.name, ad.location?.parent?.name].filter(Boolean).join('، ') || '-';
const transactionLabel = (type) => type === 'demand' ? 'تقاضای خرید' : 'واگذاری امتیاز';

async function load(page = 1) {
    loading.value = true; refreshing.value = page === meta.value.current_page; error.value = '';
    try {
        const [adsResponse, banksResponse] = await Promise.all([
            apiClient.get('/admin/ads/pending', { params: { search: search.value || undefined, bank_id: bankId.value || undefined, page, per_page: 10 } }),
            banks.value.length ? Promise.resolve({ data: { data: banks.value } }) : apiClient.get('/banks'),
        ]);
        ads.value = adsResponse.data.data || []; meta.value = adsResponse.data.meta || meta.value; banks.value = banks.value.length ? banks.value : (banksResponse.data.data || banksResponse.data || []);
        await openReviewFromQuery();
        logger.info('load', 'Pending advertisement queue loaded', { count: ads.value.length, total: meta.value.total });
    } catch (exception) { error.value = 'دریافت صف آگهی‌ها انجام نشد.'; logger.error('load', 'Pending ads failed', logException(exception)); }
    finally { loading.value = false; refreshing.value = false; }
}
async function openReviewFromQuery() {
    const reviewId = route.query.reviewId;
    if (!reviewId) return;
    const listedAd = ads.value.find((ad) => String(ad.id) === String(reviewId));
    if (listedAd) { selectedAd.value = listedAd; return; }
    try {
        const { data } = await apiClient.get(`/admin/ads/${reviewId}`);
        selectedAd.value = data.data;
    } catch (exception) {
        error.value = 'این آگهی دیگر در صف بررسی وجود ندارد یا وضعیت آن تغییر کرده است.';
        logger.warn('openReviewFromQuery', 'Requested review ad unavailable', logException(exception));
    }
}
async function approve() { if (!approveTarget.value) return; acting.value = true; try { await apiClient.patch(`/admin/ads/${approveTarget.value.id}/approve`); removeFromQueue(approveTarget.value.id); approveTarget.value = null; } catch (exception) { error.value = 'آگهی دیگر در وضعیت انتظار نیست یا تایید آن انجام نشد.'; logger.error('approve', 'Ad approval failed', logException(exception)); await load(meta.value.current_page); } finally { acting.value = false; } }
async function reject() { if (!rejectTarget.value || !rejectionReason.value) return; acting.value = true; try { const details = rejectionDetails.value.trim(); await apiClient.post(`/admin/ads/${rejectTarget.value.id}/reject`, { rejection_reason: details ? `${rejectionReason.value}: ${details}` : rejectionReason.value }); removeFromQueue(rejectTarget.value.id); closeReject(); } catch (exception) { error.value = 'آگهی دیگر در وضعیت انتظار نیست یا رد آن انجام نشد.'; logger.error('reject', 'Ad rejection failed', logException(exception)); await load(meta.value.current_page); } finally { acting.value = false; } }
function removeFromQueue(id) { ads.value = ads.value.filter((ad) => ad.id !== id); meta.value.total = Math.max(0, meta.value.total - 1); }
function closeReject() { rejectTarget.value = null; rejectionReason.value = ''; rejectionDetails.value = ''; }
function roleStatus(ad) { return ad.user?.is_verified ? 'احراز شده' : 'در انتظار'; }
onMounted(() => load());
watch(() => route.query.reviewId, () => openReviewFromQuery());
</script>

<template>
    <section class="pending-page">
        <header class="pending-header"><div><span class="pending-kicker">عملیات / صف بررسی</span><div class="pending-title-row"><h1>صف بررسی و تایید آگهی‌ها</h1><b class="queue-count">{{ queueCount }}</b></div><p>آگهی‌های ثبت‌شده را پیش از انتشار با دقت بررسی کنید.</p></div><button class="refresh-button" type="button" :disabled="loading" @click="load(meta.current_page)"><i :class="loading ? 'pi pi-spin pi-refresh' : 'pi pi-refresh'"></i>رفرش صف</button></header>
        <p v-if="error" class="pending-error" role="alert"><i class="pi pi-exclamation-triangle"></i>{{ error }}</p>
        <div class="pending-toolbar"><label class="search-box"><i class="pi pi-search"></i><input v-model="search" placeholder="عنوان، کد آگهی یا شماره موبایل" @keyup.enter="load(1)" /></label><Select v-model="bankId" :options="[{ id: null, name: 'همه بانک‌ها' }, ...banks]" optionLabel="name" optionValue="id" class="bank-select" @change="load(1)" /><button class="search-button" type="button" @click="load(1)"><i class="pi pi-search"></i>جستجو</button></div>
        <div class="pending-card"><DataTable :value="ads" dataKey="id" :loading="loading" stripedRows responsiveLayout="scroll"><Column header="کد و آگهی‌دهنده" style="min-width: 190px"><template #body="slotProps"><div class="identity-cell"><span class="avatar">{{ (slotProps.data.user?.name || 'ک').slice(0, 1) }}</span><div><strong>{{ slotProps.data.user?.name || 'بدون نام' }}</strong><small>{{ slotProps.data.user?.mobile || '-' }}</small><em :class="slotProps.data.user?.is_verified ? 'verified' : 'unverified'"><i :class="slotProps.data.user?.is_verified ? 'pi pi-check-circle' : 'pi pi-clock'"></i>{{ roleStatus(slotProps.data) }}</em></div></div></template></Column><Column header="عنوان و مشخصات آگهی" style="min-width: 220px"><template #body="slotProps"><strong class="ad-title">{{ slotProps.data.title }}</strong><span class="ad-meta">{{ slotProps.data.bank?.name || '-' }} <b>•</b> {{ slotProps.data.bank_plan?.title || slotProps.data.bankPlan?.title || 'طرح نامشخص' }}</span></template></Column><Column header="نوع معامله"><template #body="slotProps"><span class="transaction-badge" :class="slotProps.data.type === 'demand' ? 'transaction-demand' : 'transaction-supply'">{{ transactionLabel(slotProps.data.type) }}</span></template></Column><Column header="مبالغ مالی" style="min-width: 150px"><template #body="slotProps"><div class="money-cell"><strong>{{ formatMoney(slotProps.data.loan_amount) }}</strong><small>واگذاری: {{ formatMoney(slotProps.data.assignment_price) }}</small></div></template></Column><Column header="موقعیت"><template #body="slotProps">{{ locationLabel(slotProps.data) }}</template></Column><Column header="زمان ثبت"><template #body="slotProps"><span class="time-cell" :title="formatDate(slotProps.data.created_at)">{{ relativeTime(slotProps.data.created_at) }}</span></template></Column><Column header="عملیات فوری" style="min-width: 170px"><template #body="slotProps"><div class="action-list"><button class="action-button action-button--approve" type="button" title="تایید آگهی" @click="approveTarget = slotProps.data"><i class="pi pi-check"></i></button><button class="action-button action-button--reject" type="button" title="رد آگهی" @click="rejectTarget = slotProps.data"><i class="pi pi-times"></i></button><button class="action-button action-button--view" type="button" title="مشاهده و بازبینی کامل" @click="selectedAd = slotProps.data"><i class="pi pi-eye"></i></button></div></template></Column><template #empty><div class="empty-state"><i class="pi pi-check-circle"></i><h2>عالی است!</h2><p>هیچ آگهی در انتظار بررسی وجود ندارد.</p></div></template></DataTable><footer class="table-footer"><span>نمایش {{ ads.length }} آگهی از {{ meta.total }} آگهی</span><Paginator :first="(meta.current_page - 1) * meta.per_page" :rows="meta.per_page" :totalRecords="meta.total" :rowsPerPageOptions="[10]" @page="load($event.page + 1)" /></footer></div>
        <Dialog :visible="Boolean(selectedAd)" modal header="بازبینی کامل آگهی" class="review-dialog" :style="{ width: 'min(680px, 94vw)' }" @update:visible="(value) => !value && (selectedAd = null)"><div v-if="selectedAd" class="review-dialog"><span class="dialog-kicker">جزئیات آگهی #{{ selectedAd.id }}</span><h2>{{ selectedAd.title }}</h2><div class="review-owner"><i class="pi pi-user"></i><span>{{ selectedAd.user?.name || 'کاربر' }}</span><b>{{ selectedAd.user?.mobile || '-' }}</b></div><p>{{ selectedAd.description || 'توضیحی برای این آگهی ثبت نشده است.' }}</p><div class="review-grid"><div><small>بانک و طرح</small><strong>{{ selectedAd.bank?.name || '-' }} / {{ selectedAd.bankPlan?.title || '-' }}</strong></div><div><small>نرخ سود</small><strong>{{ selectedAd.bankPlan?.interest_rate || selectedAd.profit_rate || '-' }}٪</strong></div><div><small>مبلغ تسهیلات</small><strong>{{ formatMoney(selectedAd.loan_amount) }}</strong></div><div><small>قیمت واگذاری</small><strong>{{ formatMoney(selectedAd.assignment_price) }}</strong></div><div><small>موقعیت</small><strong>{{ locationLabel(selectedAd) }}</strong></div><div><small>تعداد اقساط</small><strong>{{ selectedAd.installment_count || 'ثبت نشده' }}</strong></div></div><div class="review-actions"><button type="button" class="approve-submit" @click="approveTarget = selectedAd; selectedAd = null"><i class="pi pi-check"></i>تایید و انتشار آگهی</button><button type="button" class="reject-submit" @click="rejectTarget = selectedAd; selectedAd = null"><i class="pi pi-times"></i>رد آگهی با ثبت علت</button><button type="button" class="cancel-button" @click="selectedAd = null">بازگشت به صف</button></div></div></Dialog>
        <Dialog v-model:visible="approveTarget" modal header="تایید سریع آگهی" :style="{ width: 'min(420px, 94vw)' }"><div class="confirm-dialog"><i class="pi pi-check-circle"></i><p>آیا از انتشار آگهی «{{ approveTarget?.title }}» اطمینان دارید؟</p><div><button type="button" class="cancel-button" @click="approveTarget = null">انصراف</button><button type="button" class="approve-submit" :disabled="acting" @click="approve">{{ acting ? 'در حال ثبت...' : 'تایید و انتشار' }}</button></div></div></Dialog>
        <Dialog :visible="Boolean(rejectTarget)" modal header="ثبت دلیل رد آگهی" :style="{ width: 'min(500px, 94vw)' }" @update:visible="(value) => !value && closeReject()"><div class="reject-dialog"><p>علت رد «{{ rejectTarget?.title }}» را مشخص کنید.</p><div v-for="reason in reasons" :key="reason" class="reason-option"><RadioButton v-model="rejectionReason" :inputId="reason" name="rejectionReason" :value="reason" /><label :for="reason">{{ reason }}</label></div><label for="rejection-details">توضیحات تکمیلی اپراتور</label><Textarea id="rejection-details" v-model="rejectionDetails" rows="4" autoResize placeholder="جزئیات لازم برای اصلاح آگهی را بنویسید..." /><button class="reject-submit" type="button" :disabled="acting || !rejectionReason" @click="reject">{{ acting ? 'در حال ثبت...' : 'ثبت نهایی رد آگهی' }}</button></div></Dialog>
    </section>
</template>

<style scoped>
.pending-page { max-width: 1440px; margin: 0 auto; }.pending-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; margin-bottom: 25px; }.pending-kicker { color: #a62626; font-family: ui-monospace, monospace; font-size: 10px; }.pending-title-row { display: flex; align-items: center; gap: 10px; }.pending-page h1 { margin: 7px 0 3px; color: #0f172a; font-size: 26px; font-weight: 900; }.pending-header p { margin: 0; color: #64748b; font-size: 12px; }.queue-count { display: grid; min-width: 27px; height: 27px; place-items: center; border-radius: 999px; background: #a62626; color: #fff; font-size: 11px; }.refresh-button, .search-button { display: inline-flex; align-items: center; gap: 7px; padding: 10px 14px; border: 1px solid #d1d5db; border-radius: 9px; background: #fff; color: #475569; cursor: pointer; font: inherit; font-size: 11px; }.refresh-button:disabled { cursor: wait; opacity: .6; }.pending-toolbar { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 16px; }.search-box { display: flex; width: min(350px, 100%); align-items: center; gap: 9px; padding: 0 14px; border: 1px solid #d1d5db; border-radius: 12px; background: #fff; color: #94a3b8; }.search-box:focus-within { border-color: #a62626; box-shadow: 0 0 0 3px #fee2e2; }.search-box input { width: 100%; padding: 11px 0; border: 0; outline: 0; font: inherit; font-size: 11px; }.bank-select { min-width: 160px; border-radius: 12px; border-color: #d1d5db; }.search-button { border-color: #a62626; background: #a62626; color: #fff; }.pending-card { overflow: hidden; border: 1px solid rgba(229, 231, 235, .8); border-radius: 16px; background: #fff; box-shadow: 0 3px 12px #0f172a0a; }.pending-card :deep(.p-datatable) { font-size: 11px; }.pending-card :deep(.p-datatable-thead > tr > th) { padding: 14px 13px; border-bottom: 1px solid #e5e7eb; background: rgba(249, 250, 251, .9); color: #374151; font-size: 10px; font-weight: 800; text-align: right; }.pending-card :deep(.p-datatable-tbody > tr:hover) { background: rgba(248, 250, 252, .8); }.pending-card :deep(.p-datatable-tbody > tr > td) { padding: 13px; border-bottom: 1px solid #f3f4f6; color: #475569; vertical-align: middle; }.identity-cell { display: flex; align-items: center; gap: 9px; }.avatar { display: grid; width: 32px; height: 32px; flex: 0 0 32px; place-items: center; border-radius: 50%; background: #fee2e2; color: #a62626; font-weight: 800; }.identity-cell strong, .identity-cell small, .identity-cell em { display: block; }.identity-cell strong { color: #1f2937; font-size: 11px; }.identity-cell small { margin-top: 3px; color: #9ca3af; font-family: ui-monospace, monospace; font-size: 9px; direction: ltr; text-align: right; }.identity-cell em { width: fit-content; margin-top: 4px; padding: 2px 5px; border-radius: 8px; font-size: 8px; font-style: normal; }.identity-cell em i { margin-left: 3px; }.verified { background: #ecfdf5; color: #047857; }.unverified { background: #fffbeb; color: #b45309; }.ad-title { display: block; max-width: 210px; overflow: hidden; color: #1f2937; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }.ad-meta { display: block; margin-top: 5px; color: #9ca3af; font-size: 9px; }.ad-meta b { color: #d1d5db; }.transaction-badge { display: inline-flex; padding: 5px 8px; border-radius: 999px; font-size: 9px; font-weight: 700; white-space: nowrap; }.transaction-supply { background: #ecfdf5; color: #047857; }.transaction-demand { background: #eff6ff; color: #1d4ed8; }.money-cell strong, .money-cell small { display: block; }.money-cell strong { color: #334155; font-size: 10px; }.money-cell small { margin-top: 4px; color: #94a3b8; font-size: 9px; }.time-cell { color: #64748b; font-size: 9px; white-space: nowrap; }.action-list { display: flex; gap: 4px; }.action-button { display: grid; width: 30px; height: 30px; place-items: center; border: 0; border-radius: 8px; cursor: pointer; }.action-button--approve { background: #dcfce7; color: #15803d; }.action-button--approve:hover { background: #bbf7d0; }.action-button--reject { background: #fee2e2; color: #dc2626; }.action-button--reject:hover { background: #fecaca; }.action-button--view { background: #eef2ff; color: #4f46e5; }.action-button--view:hover { background: #e0e7ff; }.table-footer { display: flex; align-items: center; justify-content: space-between; padding: 8px 15px 8px 10px; color: #6b7280; font-size: 10px; }.table-footer :deep(.p-paginator) { justify-content: flex-start; padding: 4px 0; direction: rtl; }.table-footer :deep(.p-paginator-page.p-highlight) { border-color: #a62626; background: #a62626; color: #fff; }.table-footer :deep(.p-paginator-page), .table-footer :deep(.p-paginator-prev), .table-footer :deep(.p-paginator-next) { min-width: 30px; height: 30px; border-radius: 8px; color: #64748b; }.empty-state { padding: 50px 20px; color: #9ca3af; text-align: center; }.empty-state i { display: block; margin-bottom: 10px; color: #22c55e; font-size: 38px; }.empty-state h2 { margin: 0 0 5px; color: #334155; font-size: 16px; }.empty-state p { margin: 0; font-size: 11px; }.pending-error { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; padding: 10px 13px; border-radius: 8px; background: #fef2f2; color: #b91c1c; font-size: 11px; }.review-dialog h2 { margin: 7px 0; color: #1e293b; font-size: 19px; }.dialog-kicker { color: #a62626; font-size: 10px; }.review-dialog > p { color: #64748b; font-size: 12px; line-height: 2; }.review-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-top: 18px; }.review-grid div { padding: 11px; border-radius: 8px; background: #f8fafc; }.review-grid small, .review-grid strong { display: block; }.review-grid small { color: #94a3b8; font-size: 9px; }.review-grid strong { margin-top: 4px; color: #334155; font-size: 11px; }.confirm-dialog { text-align: center; }.confirm-dialog > i { color: #16a34a; font-size: 30px; }.confirm-dialog p { color: #475569; font-size: 12px; }.confirm-dialog > div { display: flex;